import { cc } from "sinwan/component";

import { Slot } from "sinwan-ui-core/slot";
import { cn } from "@/lib/utils";
import { PopoverContent as PopoverContentPrimitive, PopoverRoot } from "sinwan-ui-core/overlay";
import {
  useHoverCardContent,
  useHoverCardTrigger,
  type HoverCardContentProps,
  type HoverCardProps,
  type HoverCardTriggerProps,
} from "./useHoverCard";

function HoverCard(props: HoverCardProps) {
  return <PopoverRoot {...props} />;
}

const HoverCardTrigger = cc(function HoverCardTrigger({
  children,
  class: className,
  asChild,
}: HoverCardTriggerProps) {
  const trigger = useHoverCardTrigger();
  if (asChild) {
    return (
      <Slot class={className} {...trigger.handlers}>
        {children}
      </Slot>
    );
  }
  return (
    <button
      type="button"
      data-slot="hover-card-trigger"
      class={className}
      aria-expanded={trigger.open.value}
      {...trigger.handlers}
    >
      {children}
    </button>
  );
});

function HoverCardContent({
  class: className,
  align = "center",
  sideOffset = 4,
  side,
  children,
}: HoverCardContentProps) {
  const content = useHoverCardContent();
  return (
    <PopoverContentPrimitive
      align={align}
      side={side}
      sideOffset={sideOffset}
      onmouseenter={content.onmouseenter}
      onmouseleave={content.onmouseleave}
      class={cn(
        "z-50 w-64 rounded-lg bg-popover p-2.5 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-hidden duration-200 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95 data-closed:!fill-mode-forwards",
        className,
      )}
    >
      {children}
    </PopoverContentPrimitive>
  );
}

export { HoverCard, HoverCardContent, HoverCardTrigger };

export { HoverCard, HoverCardContent, HoverCardTrigger } from "./hover-card";
export {
  useHoverCard,
  useHoverCardContent,
  useHoverCardTrigger,
  type HoverCardContentProps,
  type HoverCardContentReturn,
  type HoverCardContext,
  type HoverCardProps,
  type HoverCardTriggerHandlers,
  type HoverCardTriggerProps,
  type HoverCardTriggerReturn,
} from "./useHoverCard";

import { inject, onUnmounted, type SinwanNode } from "sinwan/component";
import type { Computed, Signal } from "sinwan/reactivity";

import { PopoverKey, type OpenApi } from "sinwan-ui-core/overlay";
import type { Align, Placement } from "sinwan-ui-core/floating";

export type HoverCardContext = OpenApi & { placement: Placement; align: Align };

export type HoverCardProps = {
  children?: SinwanNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
};

export type HoverCardTriggerProps = {
  children?: SinwanNode;
  class?: string;
  asChild?: boolean;
};

export type HoverCardContentProps = {
  children?: SinwanNode;
  class?: string;
  align?: Align;
  side?: Placement;
  sideOffset?: number;
};

export type HoverCardTriggerHandlers = {
  onmouseenter: () => void;
  onmouseleave: () => void;
  onfocus: () => void;
  onblur: () => void;
  ref: (el: HTMLElement | null) => void;
};

export type HoverCardTriggerReturn = {
  open: Signal<boolean> | Computed<boolean>;
  handlers: HoverCardTriggerHandlers;
};

export type HoverCardContentReturn = {
  onmouseenter: () => void;
  onmouseleave: () => void;
};

const OPEN_DELAY_MS = 100;
const CLOSE_DELAY_MS = 120;

/**
 * Inject the popover context provided by `<HoverCard />`.
 */
export function useHoverCard(consumer = "useHoverCard"): HoverCardContext {
  const context = inject(PopoverKey);
  if (!context) {
    throw new Error(`${consumer} must be used within a <HoverCard />`);
  }
  return context;
}

/**
 * Trigger behavior: opens after a short hover/focus delay (unless the
 * reopen lock is active) and requests a delayed close on leave/blur.
 */
export function useHoverCardTrigger(): HoverCardTriggerReturn {
  const api = useHoverCard("HoverCardTrigger");
  let openTimer: number | undefined;
  const clearOpenTimer = () => {
    if (openTimer !== undefined) {
      window.clearTimeout(openTimer);
      openTimer = undefined;
    }
  };
  const show = () => {
    if (api.isHoverOpenBlocked()) return;
    api.cancelClose();
    clearOpenTimer();
    openTimer = window.setTimeout(() => {
      openTimer = undefined;
      if (api.isHoverOpenBlocked()) return;
      api.setOpen(true);
    }, OPEN_DELAY_MS);
  };
  const hide = () => {
    clearOpenTimer();
    api.requestClose(CLOSE_DELAY_MS);
  };
  onUnmounted(clearOpenTimer);
  return {
    open: api.open,
    handlers: {
      onmouseenter: () => {
        api.setPointerOverTrigger(true);
        show();
      },
      onmouseleave: () => {
        api.setPointerOverTrigger(false);
        hide();
      },
      onfocus: show,
      onblur: hide,
      ref: (el) => {
        api.triggerEl.value = el;
      },
    },
  };
}

/**
 * Content behavior: hovering the card keeps it open; leaving requests a
 * delayed close.
 */
export function useHoverCardContent(): HoverCardContentReturn {
  const api = useHoverCard("HoverCardContent");
  return {
    onmouseenter: () => {
      api.cancelClose();
      api.setOpen(true);
    },
    onmouseleave: () => {
      api.requestClose(CLOSE_DELAY_MS);
    },
  };
}
